// =====================================
// Type Definitions for CBT Application
// =====================================

// Config types
export interface ExamConfig {
    exam_name: string;
    exam_duration: number; // in minutes
    max_violations: number;
    auto_submit: boolean;
    shuffle_questions: boolean;
    admin_password?: string;
    live_score_pin?: string;
    exam_pin?: string;
    exam_status?: 'OPEN' | 'CLOSED';
    admin_wa?: string;  // nomor WA admin sekolah, misal "628123456789"
    exam_mapel?: string; // id_mapel yang diujikan, kosong = semua mapel
    exam_kumpulan?: string; // daftar id kumpulan dipisah koma, kosong = semua yang aktif
    kkm?: number; // handleGetConfig resolve Config.kkm; fallback 70
    // Turunan aman dari Config.exam_pin: hanya "PIN dibutuhkan atau tidak",
    // PIN-nya sendiri tidak pernah meninggalkan server. Opsional karena tenant
    // yang GAS-nya belum di-deploy ulang belum mengirimkannya.
    isPinRequired?: boolean;
}

/** Ringkasan layar "Adakan Ujian": konfigurasi aktif + jumlah soal aktif per mapel. */
export interface ExamSummary {
    exam_name: string;
    exam_mapel: string;
    exam_duration: number;
    exam_status: 'OPEN' | 'CLOSED';
    question_count: number;
    question_counts?: Record<string, number>;
    /** Kumpulan yang dipilih guru. Kosong = semua kumpulan aktif pada mapel itu. */
    exam_kumpulan?: string[];
    collections?: QuestionCollection[];
}

/** Payload satu aksi simpan konfigurasi ujian; server memvalidasi ulang semuanya. */
export interface SaveExamConfigInput {
    exam_name: string;
    exam_mapel: string;
    exam_duration: number;
    exam_status: 'OPEN' | 'CLOSED';
    exam_kumpulan?: string[];
}

// User types
export interface User {
    id_siswa: string;
    username: string;
    /**
     * Password login siswa, hanya dikirim pada payload getUsers (admin-only) untuk
     * dicetak di kartu peserta. Jangan diteruskan ke payload siswa/monitoring/publik.
     */
    password?: string;
    nama_lengkap: string;
    kelas: string;
    status_login?: boolean;
    waktu_mulai?: string;
    waktu_selesai?: string;
    skor_akhir?: number;
    violation_count?: number;
    status_ujian: 'BELUM' | 'SEDANG' | 'SELESAI' | 'DISKUALIFIKASI';
    last_seen?: string;
    // Nilai beku milik attempt, dikirim GAS saat login/re-entry. exam_duration di
    // sini adalah durasi attempt, bukan Config terbaru: perubahan Config setelah
    // siswa mulai tidak boleh menggeser deadline-nya.
    exam_duration?: number;
    exam_id?: string;    // identitas/revisi ujian yang dibekukan untuk attempt ini
    exam_mapel?: string; // mapel beku milik attempt
    mapel_diujikan?: string; // id_mapel yang diujikan saat submit, diisi GAS
    /** Rujukan foto siswa di Drive (Users kolom 16); kosong = belum ada foto. */
    foto_url?: string;
    saved_answers?: AnswersRecord | null; // recovered answers from server (col 14)
}

// Question types
//
// QUESTION_TYPES adalah daftar canonical seluruh tipe soal yang dikenal model.
// QUESTION_TYPES_IMPLEMENTED adalah bagian yang benar-benar sudah didukung
// end-to-end (form, renderer, scoring GAS). Tipe canonical yang belum
// terimplementasi sengaja tetap tercantum agar kontrak dan sanitizer sudah punya
// bentuk yang benar; GAS tetap menolaknya sampai tipe tersebut dikerjakan.
export const QUESTION_TYPES = ['SINGLE', 'COMPLEX', 'TRUE_FALSE', 'MATCHING', 'FILL_IN'] as const;
export const QUESTION_TYPES_IMPLEMENTED = ['SINGLE', 'COMPLEX', 'TRUE_FALSE', 'MATCHING', 'FILL_IN'] as const;

export const QUESTION_WRITE_FIELDS = [
    'id_soal', 'nomor_urut', 'tipe', 'pertanyaan', 'gambar_url',
    'opsi_a', 'opsi_b', 'opsi_c', 'opsi_d', 'opsi_e',
    'kunci_jawaban', 'bobot', 'kategori', 'id_mapel', 'data_soal', 'id_kumpulan',
] as const;

export const STUDENT_QUESTION_FIELDS = [
    'id_soal', 'nomor_urut', 'tipe', 'pertanyaan', 'gambar_url',
    'opsi_a', 'opsi_b', 'opsi_c', 'opsi_d', 'opsi_e',
    'bobot', 'kategori', 'id_mapel', 'nama_mapel', 'data_soal',
] as const;

export const ADMIN_ONLY_QUESTION_FIELDS = ['kunci_jawaban', 'status_soal', 'versi_dari', 'id_kumpulan'] as const;

export type QuestionType = (typeof QUESTION_TYPES)[number];
export type ImplementedQuestionType = (typeof QUESTION_TYPES_IMPLEMENTED)[number];

/** Item bernomor pada data soal terstruktur. `teks` adalah rich text. */
export interface QuestionDataItem {
    id: string;
    teks: string;
}

export interface TrueFalseQuestionData {
    pernyataan: QuestionDataItem[];
}

export interface MatchingQuestionData {
    kiri: QuestionDataItem[];
    kanan: QuestionDataItem[];
}

export interface FillInQuestionData {
    petunjuk: string;
}

/** SELALU student-visible; kunci jawaban tidak boleh masuk ke sini. */
export type QuestionData = TrueFalseQuestionData | MatchingQuestionData | FillInQuestionData;

export interface QuestionBase {
    id_soal: string;
    nomor_urut: number;
    pertanyaan: string;
    gambar_url?: string | null;
    bobot: number;
    kategori?: string | null;
    id_mapel?: string | null;
    nama_mapel?: string | null;
}

export interface LegacyQuestionOptions {
    opsi_a: string;
    opsi_b: string;
    opsi_c: string;
    opsi_d: string;
    opsi_e?: string | null;
}

export interface SingleQuestion extends QuestionBase, LegacyQuestionOptions {
    tipe: 'SINGLE';
    data_soal?: never;
}

export interface ComplexQuestion extends QuestionBase, LegacyQuestionOptions {
    tipe: 'COMPLEX';
    data_soal?: never;
}

export interface TrueFalseQuestion extends QuestionBase {
    tipe: 'TRUE_FALSE';
    data_soal: TrueFalseQuestionData;
}

export interface MatchingQuestion extends QuestionBase {
    tipe: 'MATCHING';
    data_soal: MatchingQuestionData;
}

export interface FillInQuestion extends QuestionBase {
    tipe: 'FILL_IN';
    data_soal: FillInQuestionData;
}

/** Canonical student-visible model, discriminated by `tipe`. */
export type StudentQuestion =
    | SingleQuestion
    | ComplexQuestion
    | TrueFalseQuestion
    | MatchingQuestion
    | FillInQuestion;

/** Nama lama dipertahankan sebagai alias student-safe. */
export type Question = StudentQuestion;
export type ImplementedStudentQuestion = Extract<StudentQuestion, { tipe: ImplementedQuestionType }>;

/** Carrier Sheet/API tetap string: legacy (`B`, `A,C`) atau JSON ter-serialisasi. */
export type SerializedQuestionAnswerKey = string;

export interface QuestionAdminFields {
    kunci_jawaban: SerializedQuestionAnswerKey;
    status_soal: 'AKTIF' | 'ARSIP';
    versi_dari: string | null;
    /**
     * Kumpulan soal tempat soal ini berada (Questions kolom 18). Kosong pada
     * payload tulis berarti "biarkan seperti sekarang"; pada proyeksi admin,
     * soal yang belum dikelompokkan dilaporkan sebagai KUMPULAN_BAWAAN_ID.
     */
    id_kumpulan?: string | null;
}

/** Wadah bernama milik guru di Bank Soal. Nonaktif tidak pernah berarti terhapus. */
export interface QuestionCollection {
    id_kumpulan: string;
    nama_kumpulan: string;
    id_mapel: string;
    status: 'AKTIF' | 'NONAKTIF';
    jumlah_soal: number;
    terakhir_dipakai?: string;
    /** true = bucket bawaan berisi soal yang belum pernah dikelompokkan. */
    bawaan?: boolean;
}

/** Id bucket bawaan; sama dengan KUMPULAN_LEGACY_ID di backend. */
export const KUMPULAN_BAWAAN_ID = 'K_LAMA';

export type AdminQuestion<T extends StudentQuestion = StudentQuestion> =
    T extends StudentQuestion ? T & QuestionAdminFields : never;
export type ImplementedAdminQuestion = AdminQuestion<ImplementedStudentQuestion>;

/**
 * Payload create/update. `data_soal` writeable dan tersimpan pada Questions kolom
 * 17; untuk SINGLE/COMPLEX tipenya tetap `never` karena keduanya tidak punya isi
 * terstruktur.
 */
export type QuestionWritePayload<T extends ImplementedAdminQuestion = ImplementedAdminQuestion> =
    T extends T ? Omit<T, 'nama_mapel' | 'status_soal' | 'versi_dari'> : never;

/**
 * Kunci FILL_IN (admin-only, kolom 11). accepted_answers adalah plain text yang
 * dibandingkan exact setelah normalisasi; flag-nya adalah metadata kunci dan
 * tidak pernah ikut ke siswa.
 */
export interface FillInAnswerKey {
    accepted_answers: string[];
    case_sensitive?: boolean;
    trim?: boolean;
}

// Answer types
export type TrueFalseValue = 'BENAR' | 'SALAH';
export type TrueFalseAnswer = Record<string, TrueFalseValue>;
/** MATCHING: id item kiri → id item kanan. Parsial (sebagian kiri) tetap sah. */
export type MatchingAnswer = Record<string, string>;
export type Answer = string | string[] | TrueFalseAnswer | MatchingAnswer;
export type AnswersRecord = Record<string, Answer>;

// Response from exam
export interface ExamResponse {
    timestamp: string;
    id_siswa: string;
    nama_lengkap: string;
    kelas: string;
    jawaban_raw: string;
    skor_akhir: number;
    durasi_ujian: number;
    log_violation: string;
    ip_address?: string;
    // Kolom append-only: hanya ada pada Responses yang ditulis sejak exam binding.
    exam_id?: string;
    exam_mapel?: string;
}

// Live Score types
export interface LiveScoreEntry {
    rank: number;
    nama: string;
    kelas: string;
    skor: number;
    status: 'SELESAI' | 'DISKUALIFIKASI' | 'SEDANG' | 'BELUM';
    waktu_selesai: string;
    waktu_submit_ms: number;
}

export interface LiveScoreStats {
    total: number;
    sedang: number;
    selesai: number;
    diskualifikasi: number;
    belum: number;
}

// API Response types
export interface ApiResponse<T = unknown> {
    success: boolean;
    message?: string;
    // Sebab kegagalan yang dapat dibaca program. Penolakan bisnis dari GAS tidak
    // memakainya, jadi kehadiran `code` berarti kegagalan teknis (timeout,
    // jaringan, tenant, konfigurasi), bukan jawaban "tidak" dari aturan ujian.
    code?: 'timeout' | 'network' | 'invalid_response' | 'upstream_timeout'
        | 'upstream_error' | 'upstream_invalid' | 'tenant_not_found' | 'tenant_config'
        | 'server_config' | 'unauthenticated' | 'forbidden' | 'validation' | 'bad_request';
    data?: T;
    stats?: LiveScoreStats;
    score?: string;
    status?: string;
    violations?: number;
    disqualified?: boolean;
    archived?: boolean; // deleteQuestion: soal diarsipkan, bukan dihapus
    versioned?: boolean; // updateQuestion: perubahan disimpan sebagai versi baru
    id_soal?: string; // id soal hasil create atau versi baru
    previous_id_soal?: string; // id soal versi historis yang diarsipkan
}

// Exam State (for Zustand/IndexedDB)
export interface ExamState {
    id_siswa: string;
    nama_lengkap: string;
    kelas: string;
    answers: AnswersRecord;
    lastSync: Date | null;
    timeRemaining: number; // in seconds
    violations: number;
    currentQuestion: number;
    isSubmitted: boolean;
}

// Violation types
export type ViolationType =
    | 'tab_switch'
    | 'blur'
    | 'exit_fullscreen'
    | 'copy'
    | 'paste'
    | 'contextmenu'
    | 'devtools'
    | 'keyboard_shortcut';

export interface Kelas {
    id_kelas: string;
    nama_kelas: string;
    tingkat: string;
}

export interface MataPelajaran {
    id_mapel: string;
    kode_mapel: string;
    nama_mapel: string;
}

// CP Registry types
export type PhaseName = 'fase_A' | 'fase_B' | 'fase_C' | 'fase_D' | 'fase_E' | 'fase_F';

export interface CPElement {
    elemen: Record<string, string>;
}

export interface PhaseData {
    jenjang: string;
    mapel: Record<string, CPElement>;
    mata_pelajaran_pilihan?: Record<string, CPElement>;
}
